#include <iostream>
using namespace std;

double calc(double a, char op, double b) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': return b != 0 ? a / b : 0;
        default: return 0;
    }
}

int main() {
    double a, b;
    char op;
    cin >> a >> op >> b;
    cout << a << " " << op << " " << b << " = " << calc(a, op, b) << endl;
    return 0;
}

#include <iostream>
using namespace std;

double km_to_miles(double km) { return km * 0.621371; }
double c_to_f(double c) { return c * 9 / 5 + 32; }

int main() {
    cout << km_to_miles(10) << endl;
    cout << c_to_f(30) << endl;
    return 0;
}

